arguments.command:
cd /tmp/vally-eval-trial-gDIW6y && mkdir -p tests/CheckoutPricing.UnitTests/Checkout && cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Gold }

public sealed record CalculatePayableTotalRequest(CustomerTier Tier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalRequest request) => request.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var handler = new CalculatePayableTotalHandler();

        var payable = handler.Handle(new CalculatePayableTotalRequest(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -25

